def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height separator lines divide the grid into panels.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_bands = []
    start = 0
    for r in sep_rows + [h]:
        if start < r:
            row_bands.append((start, r))
        start = r + 1

    col_bands = []
    start = 0
    for c in sep_cols + [w]:
        if start < c:
            col_bands.append((start, c))
        start = c + 1

    divider_cells = set(sep_rows)
    background_counts = {}
    for r, (r0, r1) in enumerate(row_bands):
        for c, (c0, c1) in enumerate(col_bands):
            for i in range(r0, r1):
                for j in range(c0, c1):
                    color = grid[i][j]
                    background_counts[color] = background_counts.get(color, 0) + 1

    background = max(background_counts, key=background_counts.get)

    result = []
    for r0, r1 in row_bands:
        out_row = []
        for c0, c1 in col_bands:
            marks = sum(
                grid[i][j] != background
                for i in range(r0, r1)
                for j in range(c0, c1)
            )
            out_row.append(1 if marks == 2 else background)
        result.append(out_row)
    return result
